require_once __DIR__.'/../../includes/auth.php'; require_once __DIR__.'/../../includes/csrf.php'; require_once __DIR__.'/../../config/database.php'; $a=require_permission('marks.edit'); if(!in_array($a['role_name']??'', ['admin','dept_admin','super_admin'],true)){http_response_code(403);exit('403 Forbidden');} enforceCsrf(); $id=(int)($_POST['entry_id']??0);$reason=trim($_POST['reason']??'');$new=$_POST['new_marks']??'';if(!$id||$reason===''||!is_numeric($new))exit('Valid mark and reason required.'); try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT fme.*,s.batch_id,COALESCE(NULLIF(CASE WHEN LOWER(at.assessment_type_name) LIKE '%internal%' THEN psm.subject_max_internal WHEN LOWER(at.assessment_type_name) LIKE '%mid%' THEN psm.subject_max_midterm WHEN LOWER(at.assessment_type_name) LIKE '%final%' THEN psm.subject_max_final END,0),CASE WHEN LOWER(at.assessment_type_name) LIKE '%internal%' THEN p.max_internal WHEN LOWER(at.assessment_type_name) LIKE '%mid%' THEN p.max_midterm WHEN LOWER(at.assessment_type_name) LIKE '%final%' THEN p.max_final END,sfm.max_marks) max_marks FROM faculty_marks_entry fme JOIN students s ON s.student_id=fme.student_id JOIN papers p ON p.paper_id=fme.paper_id JOIN assessment_types at ON at.assessment_type_id=fme.assessment_type_id JOIN paper_subject_mapping psm ON psm.batch_id=s.batch_id AND psm.paper_id=fme.paper_id AND psm.subject_id=fme.subject_id LEFT JOIN subject_faculty_mapping sfm ON sfm.batch_id=s.batch_id AND sfm.subject_id=fme.subject_id AND sfm.faculty_id=fme.faculty_id WHERE fme.entry_id=:id AND fme.paper_id IS NOT NULL FOR UPDATE");$q->execute([':id'=>$id]);$o=$q->fetch();if(!$o||$new<0||$new>(float)$o['max_marks'])throw new RuntimeException('Invalid current mapping or maximum.');$u=$pdo->prepare('UPDATE faculty_marks_entry SET marks_obtained=:m,is_absent=0,graded_at=CURRENT_TIMESTAMP WHERE entry_id=:id');$u->execute([':m'=>(float)$new,':id'=>$id]);$x=$pdo->prepare("INSERT INTO admin_marks_audit(entry_id,student_id,batch_id,paper_id,subject_id,assessment_type_id,faculty_id,old_marks,new_marks,old_is_absent,new_is_absent,admin_name,reason,edit_mode) VALUES(:e,:s,:b,:p,:sub,:at,:f,:om,:nm,:oa,0,:an,:r,'FULL_ADMIN')");$x->execute([':e'=>$id,':s'=>$o['student_id'],':b'=>$o['batch_id'],':p'=>$o['paper_id'],':sub'=>$o['subject_id'],':at'=>$o['assessment_type_id'],':f'=>$o['faculty_id'],':om'=>$o['marks_obtained'],':nm'=>(float)$new,':oa'=>$o['is_absent'],':an'=>$a['full_name']??'Admin',':r'=>$reason]);setFlash('success', 'Mark updated successfully and audit log recorded.');$pdo->commit();header('Location: full_edit.php?batch_id='.(int)$o['batch_id'].'&student_id='.(int)$o['student_id']);exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(400);exit($e->getMessage());}
